type Action =
  | { type: 'refresh' }
  | { type: 'loaded'; items: Item[] }
  | { type: 'failed'; message: string };
type UiState = { items: Item[]; loading: boolean; error: string | null };

function reduce(state: UiState, action: Action): UiState {
  switch (action.type) {
    case 'refresh': return { ...state, loading: true, error: null };
    case 'loaded':  return { items: action.items, loading: false, error: null };
    case 'failed':  return { ...state, loading: false, error: action.message };
    default: { const exhaustive: never = action; return state; }
  }
}
